IDS_B23 = ["YM-044","YM-045","YM-047","YM-048","YM-049","YM-050","YM-052","YM-053","YM-054","YM-055","YM-057","YM-058","YM-059","YM-060","YM-062","YM-063","YM-064","YM-065","YM-067","YM-068"]
